# ------------------------------------------------------------------ 2 ba, confirmation, tag questions
_BA = [("Taga-Ohio ba si Lucia?", "Is Lucia from Ohio?"), ("Oo. Taga-Ohio siya.", "Yes. She is from Ohio."), ("Hindi. Hindi taga-Ohio si Lucia. Taga-Kansas siya.", "No. Lucia is not from Ohio. She is from Kansas."), ("Hindi ba inhinyero si Jason?", "Isn’t Jason an engineer?"), ("Oo. Inhinyero si Jason.", "Yes. Jason is an engineer."), ("Hindi ba inhinyero siya?", "Isn’t he an engineer?"), ("Oo. Inhinyero siya.", "Yes. He is an engineer."), ("Medyor si Simon, hindi ba?", "Simon is a major, isn’t he?"), ("Medyor si Simon, ano?", "Simon is a major, isn’t he?"), ("Oo. Medyor si Simon.", "Yes. Simon is a major."), ("Hindi. Hindi medyor si Simon.", "No. Simon is not a major."), ("Hindi. Hindi siya medyor.", "No. He is not a major.")]
_CONF = [("Hindi ba doktor si Celso?", "Isn’t Celso a doctor?"), ("Oo. Inhinyero siya.", "Yes. He is. (answer 1 in the book’s example about Jason)"), ("Hindi.", "No."), ("Hindi. Hindi siya inhinyero. Kusinero siya.", "No. He is not an engineer. He is a cook.")]
_TAG = [("Hindi siya medyor, hindi ba?", "He is not a major, is he?"), ("Hindi siya medyor, ano?", "He is not a major, is he?"), ("Opo. Hindi siya medyor.", "Yes, sir/ma’am. He is not a major. (agreeing with the statement)"), ("Hindi. Medyor po siya.", "No, sir/ma’am. He is a major. (disagreeing, because he is in fact a major)")]
