_TRK = [("Mabait ba ang nanay ni Leoncio?", "Is Leoncio’s mother nice?"), ("Taga-saan ang nanay at tatay mo?", "Where are your mother and father from?"), ("Heneral si Peter, hindi ba?", "Peter is a general, isn’t he?"), ("Taga-rito ka, ano?", "You are from here, aren’t you?"), ("Hindi ba negosyante ang tito mo?", "Isn’t your uncle a businessman?")]
L2 = lesson(
    "C2 L3 · The particle ba, confirmation questions and tag questions",
    "Taga-Ohio ba si Lucia? · Hindi ba inhinyero si Jason? · Medyor si Simon, hindi ba? · ano?",
    requires=[],
    cards=[
        card("The enclitic particle ba", "Yes/no questions in Tagalog use the enclitic particle ba. Enclitic particles are one- and two-syllable words (like naman) that normally come after the first full word of the sentence. Ba signals a yes/no question and has no English equivalent. It is usually left out when an interrogative like “who”, “what” or “when” is already in the sentence, but it can be used with these to make a question more emphatic or to clarify a response. A question can be answered with a short “yes” or “no” or with a full sentence.", examples=passage(_BA)),
        card("Confirmation questions", "The English question “Isn’t Celso a doctor?” is Hindi ba doktor si Celso?", examples=passage(_CONF)),
        card("Tag questions", "There are only two question tags in Tagalog, and they are easier than the English ones: ano? and hindi ba?. They alternate freely and do not depend on the phrase before them, unlike English, where the tag reflects the tense and a negative phrase gets an affirmative tag.", examples=passage(_TAG)),
        card("Note on agreeing and disagreeing", "In the last example, Opo. Hindi siya medyor means the person agrees with the statement that he is not a major; Hindi. Medyor po siya means the person disagrees, because he is in fact a major. English speakers must get used to this: it is the opposite of their usual answers to such questions (Oo agrees with the content of the statement; Hindi contradicts it)."),
        card("Transcription and translation (FLO Skills, Activities 1 and 2, the book’s key)", "", examples=passage(_FK + _TRK)),
        card("Activities left out", "The audio of the transcription activity."),
    ],
    exercises=uniq(
        tr_q(_BA) + rev_q(_BA[:2]) + tr_q(_CONF) + tr_q(_TAG) + tr_q(_FK) + tr_q(_TRK) + rev_q(_TRK)
        + [M("What does ba signal?", "A yes/no question", ["A past tense", "A plural", "A name"], "Ba."), M("What are the two question tags in Tagalog?", "ano? and hindi ba?", ["oo? and hindi?", "ba? and po?", "naman? and rin?"], "Ano and hindi ba."), M("Is ba translated into English?", "No, it has no English equivalent", ["Yes, as “is”", "Yes, as “not”", "Yes, as “who”"], "Ba has no equivalent."), M("Where does an enclitic particle like ba normally appear?", "After the first full word of the sentence", ["At the very end", "Before the first word", "Before the verb only"], "Enclitic."), M("When is ba usually left out?", "When an interrogative like who, what or when is already there", ["With names", "With numbers", "With ma adjectives"], "Interrogatives."), M("How do you ask “Isn’t he an engineer?”", "Hindi ba inhinyero siya?", ["Inhinyero ba siya hindi?", "Siya hindi ba inhinyero?", "Ba hindi inhinyero siya?"], "Hindi ba + predicate + subject."), M("What does Opo. Hindi siya medyor mean?", "Yes, sir/ma’am. He is not a major.", ["No. He is a major.", "He is a major.", "Is he a major?"], "Agreeing."), M("What does Hindi. Medyor po siya mean?", "No, sir/ma’am. He is a major.", ["Yes. He is not a major.", "He is not a major.", "Is he a major?"], "Disagreeing."), M("Do Tagalog tag questions depend on the preceding phrase?", "No, they alternate freely", ["Yes, as in English", "Only in the past", "Only with names"], "Always ano or hindi ba."), M("What does Heneral si Peter, hindi ba? mean?", "Peter is a general, isn’t he?", ["Is Peter a general?", "Peter is not a general.", "Who is the general?"], "Tag question.")]
        + [F("Taga-Ohio ___ si Lucia? (yes/no question)", "ba", ["po", "naman"], "Taga-Ohio ba si Lucia?"), F("___ ba inhinyero si Jason? (isn’t)", "Hindi", ["Oo", "Ano"], "Hindi ba inhinyero si Jason?"), F("Medyor si Simon, ___? (tag)", "ano", ["sino", "saan"], "Medyor si Simon, ano?"), F("Medyor si Simon, hindi ___? (tag)", "ba", ["po", "ano"], "hindi ba."), F("___. Hindi siya medyor. (agreeing, polite)", "Opo", ["Hindi", "Ano"], "Opo."), F("Katulong ba siya ___ karpintero? (or)", "o", ["at", "ay"], "o = or.")]
    ),
)

